using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithSeedData();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        #region Index

        [Fact]
        public void Index_NoParams_ReturnsViewWithPaginatedStudents()
        {
            var result = _controller.Index(null, null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(5, model.Count);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAscending()
        {
            var result = _controller.Index(null, null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal("Alexander", model[0].LastName);
            Assert.Equal("Alonso", model[1].LastName);
            Assert.Equal("Anand", model[2].LastName);
        }

        [Fact]
        public void Index_NameDescSort_OrdersByLastNameDescending()
        {
            var result = _controller.Index("name_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal("Li", model[0].LastName);
            Assert.Equal("Barzdukas", model[1].LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDateAscending()
        {
            var result = _controller.Index("Date", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal("Alexander", model[0].LastName); // 2010
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
        {
            var result = _controller.Index("date_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal("Anand", model[0].LastName); // 2013
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByLastName()
        {
            var result = _controller.Index(null, null, "Alexander", null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByFirstName()
        {
            var result = _controller.Index(null, null, "Carson", null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Carson", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchString_ResetsPageTo1()
        {
            var result = _controller.Index(null, null, "Alexander", 3);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NoSearchStringWithCurrentFilter_UsesCurrentFilter()
        {
            var result = _controller.Index(null, "Li", null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Li", model[0].LastName);
        }

        [Fact]
        public void Index_SetsViewBagSortParameters()
        {
            var result = _controller.Index(null, null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("name_desc", viewResult.ViewData["NameSortParm"]);
            Assert.Equal("Date", viewResult.ViewData["DateSortParm"]);
        }

        [Fact]
        public void Index_WithNameDescSort_SetsCorrectViewBagSortParms()
        {
            var result = _controller.Index("name_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            // When sortOrder is not null/empty, NameSortParm should be ""
            Assert.Equal("", viewResult.ViewData["NameSortParm"]);
        }

        [Fact]
        public void Index_WithDateSort_SetsDateSortParmToDateDesc()
        {
            var result = _controller.Index("Date", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("date_desc", viewResult.ViewData["DateSortParm"]);
        }

        [Fact]
        public void Index_SetsCurrentFilterInViewBag()
        {
            var result = _controller.Index(null, null, "test", null);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("test", viewResult.ViewData["CurrentFilter"]);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var studentId = _context.Students.First().ID;

            var result = _controller.Details(studentId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal(studentId, model.ID);
            Assert.Equal("Alexander", model.LastName);
        }

        [Fact]
        public void Details_ValidId_IncludesEnrollments()
        {
            var studentId = _context.Students.First().ID;

            var result = _controller.Details(studentId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.NotNull(model.Enrollments);
            Assert.Equal(2, model.Enrollments.Count);
        }

        [Fact]
        public void Details_ValidId_IncludesCoursesViaEnrollments()
        {
            var studentId = _context.Students.First().ID;

            var result = _controller.Details(studentId);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.All(model.Enrollments, e => Assert.NotNull(e.Course));
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsViewWithStudentWithDefaultEnrollmentDate()
        {
            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal(DateTime.Today.Date, model.EnrollmentDate.Date);
        }

        #endregion

        #region Create POST

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                LastName = "TestLast",
                FirstMidName = "TestFirst",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };

            var result = _controller.Create(student);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
        }

        [Fact]
        public void Create_Post_ValidStudent_SavesStudentToDatabase()
        {
            var student = new Student
            {
                LastName = "NewStudent",
                FirstMidName = "First",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };

            _controller.Create(student);

            var savedStudent = _context.Students.FirstOrDefault(s => s.LastName == "NewStudent");
            Assert.NotNull(savedStudent);
            Assert.Equal("First", savedStudent.FirstMidName);
            Assert.Equal(DateTime.Parse("2023-09-01"), savedStudent.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_MinValueEnrollmentDate_ReturnsViewWithModelError()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_DateBefore1753_ReturnsViewWithModelError()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(1752, 12, 31)
            };

            var result = _controller.Create(student);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsViewWithStudent()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                LastName = "",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };

            var result = _controller.Create(student);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Same(student, viewResult.Model);
        }

        [Fact]
        public void Create_Post_ValidDate_DoesNotAddModelError()
        {
            var student = new Student
            {
                LastName = "ValidDate",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 6, 15)
            };

            _controller.Create(student);

            Assert.False(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        #endregion

        #region Edit GET

