using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            // Drain the static queue to avoid interference between tests
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void GetNotifications_NoNotifications_ReturnsEmptyList()
        {
            // Drain queue first
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }

            var result = _controller.GetNotifications();

            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsUpTo10()
        {
            // Drain queue first
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }

            // Enqueue 15 notifications
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Test", i.ToString(), EntityOperation.CREATE, "TestUser");
            }

            var result = _controller.GetNotifications();

            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);
            // The result should contain at most 10 notifications
            var valueType = jsonResult.Value!.GetType();
            var countProp = valueType.GetProperty("count");
            Assert.NotNull(countProp);
            var count = (int)countProp.GetValue(jsonResult.Value)!;
            Assert.Equal(10, count);
        }

        [Fact]
        public void GetNotifications_DequeuesNotificationsInOrder()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }

            svc.SendNotification("Student", "1", "Alice", EntityOperation.CREATE, "Admin");
            svc.SendNotification("Course", "2", "Math101", EntityOperation.UPDATE, "Admin");

            var result = _controller.GetNotifications();

            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);
            var valueType = jsonResult.Value!.GetType();
            var notificationsProp = valueType.GetProperty("notifications");
            Assert.NotNull(notificationsProp);
            var notifications = (List<Notification>)notificationsProp.GetValue(jsonResult.Value)!;
            Assert.Equal(2, notifications.Count);
            Assert.Contains("Alice", notifications[0].Message);
            Assert.Contains("Math101", notifications[1].Message);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessJson()
        {
            var result = _controller.MarkAsRead(1);

            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);
            var valueType = jsonResult.Value!.GetType();
            var successProp = valueType.GetProperty("success");
            Assert.NotNull(successProp);
            var success = (bool)successProp.GetValue(jsonResult.Value)!;
            Assert.True(success);
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain again on cleanup
            while (_service.ReceiveNotification() != null) { }
            _service.Dispose();
        }

        #region SendNotification

        [Fact]
        public void SendNotification_Create_EnqueuesNotification()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithDisplayName_UsesDisplayNameInMessage()
        {
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("Student", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            _service.SendNotification("Student", "42", EntityOperation.CREATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            var before = DateTime.Now;
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");
            var after = DateTime.Now;

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_DelegatesToMainOverload()
        {
            _service.SendNotification("Course", "100", EntityOperation.UPDATE, "Teacher");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("100", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("ID: 100", notification.Message);
        }

        #endregion

        #region GenerateMessage

        [Fact]
        public void SendNotification_Create_GeneratesCorrectMessage()
        {
            _service.SendNotification("Student", "1", "Alice Smith", EntityOperation.CREATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("New Student 'Alice Smith' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_Update_GeneratesCorrectMessage()
        {
            _service.SendNotification("Course", "101", "Math 101", EntityOperation.UPDATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course 'Math 101' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_Delete_GeneratesCorrectMessage()
        {
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_Create_NoDisplayName_GeneratesIdBasedMessage()
        {
            _service.SendNotification("Student", "99", null, EntityOperation.CREATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_Update_NoDisplayName_GeneratesIdBasedMessage()
        {
            _service.SendNotification("Course", "42", null, EntityOperation.UPDATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course (ID: 42) has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_Delete_NoDisplayName_GeneratesIdBasedMessage()
        {
            _service.SendNotification("Department", "7", null, EntityOperation.DELETE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Department (ID: 7) has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_TreatedAsNoDisplayName()
        {
            _service.SendNotification("Student", "5", "  ", EntityOperation.CREATE, "Admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 5", notification.Message);
        }

        #endregion

        #region ReceiveNotification

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var notification = _service.ReceiveNotification();

            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_DequeuesInFIFOOrder()
        {
            _service.SendNotification("A", "1", EntityOperation.CREATE, "Admin");
            _service.SendNotification("B", "2", EntityOperation.UPDATE, "Admin");
            _service.SendNotification("C", "3", EntityOperation.DELETE, "Admin");

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();
            var third = _service.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Equal("A", first.EntityType);
            Assert.NotNull(second);
            Assert.Equal("B", second.EntityType);
            Assert.NotNull(third);
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void ReceiveNotification_RemovesFromQueue()
        {
            _service.SendNotification("Test", "1", EntityOperation.CREATE, "Admin");

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Null(second);
        }

        #endregion

        #region Queue Cap

        [Fact]
        public void SendNotification_QueueCap_DoesNotExceed500()
        {
            // Send more than 500 notifications
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Test", i.ToString(), EntityOperation.CREATE, "Admin");
            }

            // Count remaining in queue
            int count = 0;
            while (_service.ReceiveNotification() != null) count++;

            Assert.True(count <= 500, $"Queue should cap at 500, but had {count} items");
        }

        #endregion

        #region MarkAsRead

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op - just verify it doesn't throw
            var exception = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_AcceptsAnyId()
        {
            var exception = Record.Exception(() => _service.MarkAsRead(999));
            Assert.Null(exception);
        }

        #endregion

        #region Dispose

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        #endregion
    }
}

using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        #region Constructor

        [Fact]
        public void Constructor_SetsPageIndex()
        {
            var items = new List<string> { "a", "b", "c" };

            var list = new PaginatedList<string>(items, 10, 2, 3);

            Assert.Equal(2, list.PageIndex);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages_ExactDivision()
        {
            var items = new List<string> { "a", "b" };

            var list = new PaginatedList<string>(items, 10, 1, 5);

            Assert.Equal(2, list.TotalPages);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages_WithRemainder()
        {
            var items = new List<string> { "a", "b" };

            var list = new PaginatedList<string>(items, 11, 1, 5);

            Assert.Equal(3, list.TotalPages);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages_SingleItem()
        {
            var items = new List<string> { "a" };

            var list = new PaginatedList<string>(items, 1, 1, 10);

            Assert.Equal(1, list.TotalPages);
        }

        [Fact]
        public void Constructor_AddsAllItems()
        {
            var items = new List<string> { "a", "b", "c" };

            var list = new PaginatedList<string>(items, 10, 1, 5);

            Assert.Equal(3, list.Count);
            Assert.Equal("a", list[0]);
            Assert.Equal("b", list[1]);
            Assert.Equal("c", list[2]);
        }

        #endregion

        #region HasPreviousPage

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var list = new PaginatedList<string>(new List<string> { "a" }, 10, 1, 5);

            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var list = new PaginatedList<string>(new List<string> { "a" }, 10, 2, 5);

            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_ThirdPage_ReturnsTrue()
        {
            var list = new PaginatedList<string>(new List<string> { "a" }, 15, 3, 5);

            Assert.True(list.HasPreviousPage);
        }

        #endregion

        #region HasNextPage

        [Fact]
        public void HasNextPage_OnLastPage_ReturnsFalse()
        {
            var list = new PaginatedList<string>(new List<string> { "a" }, 10, 2, 5);

            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_NotOnLastPage_ReturnsTrue()
        {
            var list = new PaginatedList<string>(new List<string> { "a" }, 10, 1, 5);

            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_SinglePage_ReturnsFalse()
        {
            var list = new PaginatedList<string>(new List<string> { "a" }, 3, 1, 5);

            Assert.False(list.HasNextPage);
        }

        #endregion

        #region Create

        [Fact]
        public void Create_ReturnsCorrectPageOfItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result[0]);
            Assert.Equal(10, result[9]);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Create_SinglePage_CorrectProperties()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_MiddlePage_HasBothPreviousAndNextPage()
        {
            var source = Enumerable.Range(1, 30).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.True(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_PageSizeEqualsTotal_SinglePage()
        {
            var source = Enumerable.Range(1, 10).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        #endregion
    }
}

