using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithSeedData(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            // Add departments
            var departments = new[]
            {
                new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01") },
                new Department { DepartmentID = 2, Name = "Mathematics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01") },
                new Department { DepartmentID = 3, Name = "Engineering", Budget = 350000, StartDate = DateTime.Parse("2007-09-01") },
                new Department { DepartmentID = 4, Name = "Economics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01") }
            };
            context.Departments.AddRange(departments);
            context.SaveChanges();

            // Add instructors
            var instructors = new[]
            {
                new Instructor { LastName = "Abercrombie", FirstMidName = "Kim", HireDate = DateTime.Parse("1995-03-11"), CourseAssignments = new List<CourseAssignment>() },
                new Instructor { LastName = "Fakhouri", FirstMidName = "Fadi", HireDate = DateTime.Parse("2002-07-06"), CourseAssignments = new List<CourseAssignment>() },
                new Instructor { LastName = "Zheng", FirstMidName = "Roger", HireDate = DateTime.Parse("2004-02-12"), CourseAssignments = new List<CourseAssignment>() },
            };
            context.Instructors.AddRange(instructors);
            context.SaveChanges();

            // Add courses
            var courses = new[]
            {
                new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 3 },
                new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 4 },
                new Course { CourseID = 4041, Title = "Macroeconomics", Credits = 3, DepartmentID = 4 },
                new Course { CourseID = 1045, Title = "Calculus", Credits = 4, DepartmentID = 2 },
                new Course { CourseID = 3141, Title = "Trigonometry", Credits = 4, DepartmentID = 2 },
                new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = 1 },
                new Course { CourseID = 2042, Title = "Literature", Credits = 4, DepartmentID = 1 }
            };
            context.Courses.AddRange(courses);
            context.SaveChanges();

            // Add students
            var students = new[]
            {
                new Student { LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = DateTime.Parse("2010-09-01"), Enrollments = new List<Enrollment>() },
                new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = DateTime.Parse("2012-09-01"), Enrollments = new List<Enrollment>() },
                new Student { LastName = "Anand", FirstMidName = "Arturo", EnrollmentDate = DateTime.Parse("2013-09-01"), Enrollments = new List<Enrollment>() },
                new Student { LastName = "Barzdukas", FirstMidName = "Gytis", EnrollmentDate = DateTime.Parse("2012-09-01"), Enrollments = new List<Enrollment>() },
                new Student { LastName = "Li", FirstMidName = "Yan", EnrollmentDate = DateTime.Parse("2012-09-01"), Enrollments = new List<Enrollment>() },
            };
            context.Students.AddRange(students);
            context.SaveChanges();

            // Add enrollments
            var studentList = new List<Student>(context.Students);
            var enrollments = new[]
            {
                new Enrollment { StudentID = studentList[0].ID, CourseID = 1050, Grade = Grade.A },
                new Enrollment { StudentID = studentList[0].ID, CourseID = 4022, Grade = Grade.C },
                new Enrollment { StudentID = studentList[1].ID, CourseID = 1045, Grade = Grade.B },
                new Enrollment { StudentID = studentList[2].ID, CourseID = 2021, Grade = Grade.B },
                new Enrollment { StudentID = studentList[3].ID, CourseID = 1050 },
                new Enrollment { StudentID = studentList[4].ID, CourseID = 4041, Grade = Grade.B },
            };
            context.Enrollments.AddRange(enrollments);
            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Controllers;
