using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void DbSets_AreAccessible()
        {
            Assert.NotNull(_context.Courses);
            Assert.NotNull(_context.Enrollments);
            Assert.NotNull(_context.Departments);
            Assert.NotNull(_context.OfficeAssignments);
            Assert.NotNull(_context.CourseAssignments);
            Assert.NotNull(_context.People);
            Assert.NotNull(_context.Students);
            Assert.NotNull(_context.Instructors);
            Assert.NotNull(_context.Notifications);
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.First(s => s.LastName == "Test");
            Assert.Equal("Test", retrieved.LastName);
            Assert.Equal("Student", retrieved.FirstMidName);
            Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                LastName = "TestInstructor",
                FirstMidName = "Inst",
                HireDate = DateTime.Parse("2020-06-15"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.First(i => i.LastName == "TestInstructor");
            Assert.Equal("TestInstructor", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2020-06-15"), retrieved.HireDate);
        }

        [Fact]
        public void Student_InheritsPerson_CanQueryFromPeopleTable()
        {
            var student = new Student
            {
                LastName = "InPeople",
                FirstMidName = "Found",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var person = _context.People.FirstOrDefault(p => p.LastName == "InPeople");
            Assert.NotNull(person);
            Assert.IsType<Student>(person);
        }

        [Fact]
        public void Instructor_InheritsPerson_CanQueryFromPeopleTable()
        {
            var instructor = new Instructor
            {
                LastName = "InPeopleInst",
                FirstMidName = "Test",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var person = _context.People.FirstOrDefault(p => p.LastName == "InPeopleInst");
            Assert.NotNull(person);
            Assert.IsType<Instructor>(person);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            var instructor = new Instructor
            {
                LastName = "CompositeTest",
                FirstMidName = "Key",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            var dept = new Department { Name = "TestDept", Budget = 100, StartDate = DateTime.Today };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 5555, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var ca = new CourseAssignment { CourseID = 5555, InstructorID = instructor.ID };
            _context.CourseAssignments.Add(ca);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(5555, instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal(5555, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void OfficeAssignment_HasInstructorIdAsPrimaryKey()
        {
            var instructor = new Instructor
            {
                LastName = "OfficeTest",
                FirstMidName = "Test",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 101" };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();

            var retrieved = _context.OfficeAssignments.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Room 101", retrieved.Location);
        }

        [Fact]
        public void CanAddAndRetrieveDepartmentWithInstructor()
        {
            var instructor = new Instructor
            {
                LastName = "DeptAdmin",
                FirstMidName = "Admin",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "Physics",
                Budget = 250000,
                StartDate = DateTime.Parse("2023-09-01"),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var retrieved = _context.Departments.Include(d => d.Administrator)
                .First(d => d.Name == "Physics");
            Assert.NotNull(retrieved.Administrator);
            Assert.Equal("DeptAdmin", retrieved.Administrator.LastName);
            Assert.Equal(250000m, retrieved.Budget);
        }

        [Fact]
        public void CanAddAndRetrieveNotification()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now,
                CreatedBy = "Admin",
                IsRead = false
            };
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.First(n => n.EntityType == "Student");
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("CREATE", retrieved.Operation);
            Assert.Equal("Test message", retrieved.Message);
            Assert.Equal("Admin", retrieved.CreatedBy);
            Assert.False(retrieved.IsRead);
        }

        [Fact]
        public void Enrollment_LinksStudentAndCourse()
        {
            var dept = new Department { Name = "TestDept2", Budget = 100, StartDate = DateTime.Today };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 7777, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);

            var student = new Student
            {
                LastName = "EnrollTest",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = 7777,
                Grade = Grade.A
            };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.StudentID == student.ID && e.CourseID == 7777);
            Assert.NotNull(retrieved.Student);
            Assert.NotNull(retrieved.Course);
            Assert.Equal("EnrollTest", retrieved.Student.LastName);
            Assert.Equal("Test Course", retrieved.Course.Title);
            Assert.Equal(Grade.A, retrieved.Grade);
        }
    }
}

