[Fact]
public void SendNotification_QueueCap_DoesNotExceed500()
{
    // Send exactly 501 notifications to test the boundary
    for (int i = 0; i < 501; i++)
    {
        _service.SendNotification("Test", i.ToString(), EntityOperation.CREATE, "Admin");
    }

    // Count remaining in queue
    int count = 0;
    while (_service.ReceiveNotification() != null) count++;

    Assert.Equal(500, count);
}

[Fact]
public void SendNotification_QueueCap_TrimsOldestEntries()
{
    // Send 510 notifications
    for (int i = 0; i < 510; i++)
    {
        _service.SendNotification("Test", i.ToString(), EntityOperation.CREATE, "Admin");
    }

    // The oldest entries should have been trimmed
    var first = _service.ReceiveNotification();
    Assert.NotNull(first);
    // The first 10+ items should have been dequeued during trimming
    var firstId = int.Parse(first.EntityId);
    Assert.True(firstId >= 10, $"Expected oldest items trimmed, but first item has ID {firstId}");
}

